using marble_physics::Mem;
using marble_physics::PLAYER;

// player fields
static const uint8_t PZ = 0x14, SLOT = 0x18, STATE = 0x1a, VISIBLE = 0x1c, SX = 0x1e, SY = 0x20;
static const uint8_t GROUND_Z = 0x2a, AIR = 0x36, MASKS = 0x38, ANIM = 0x5a, SHARDS = 0x62;
static const uint8_t SHARDS_ON = 0x67, VZ = 0x08, SCORE = 0xbc, DISTANCE = 0xc4, DEATHS = 0xd2;
static const uint8_t VX = 0x00, VY = 0x04, PX = 0x0c, PY = 0x10, ZONE = 0x1b, DAMAGE = 0x57;
static const uint8_t PLAYER_BYTES = 0xe2;
static const uint8_t MASK_BYTES = 30, MASK_ENTRY = 6;
static const uint16_t MASK_BIT = 0x4000;
static const uint8_t AIRBORNE = 2;
static const uint32_t RNG = 0x4003a6;
static const uint16_t RNG_TICK = 0x100;
static const uint8_t ST_EATEN = 5, ST_DISSOLVE = 9;
static const uint32_t FRAMES_BASE = 0x20000;  // frame headers: 0x20000 + addr * 2

static uint8_t ram[marble_physics::RAM_SIZE];

static void loadRam(const MarbleDeathSegment &seg) {
  memset(ram, 0, sizeof(ram));
  for (uint8_t i = 0; i < seg.nram; i++) {
    const MarbleDeathRam &r = seg.ram[i];
    memcpy(ram + (r.addr - marble_physics::RAM_BASE), r.bytes, r.len);
  }
}

// frame header drawn from +0x5a (states 1, 2, 5, 9) and the shard overlay +0x62, 0 if none
static uint32_t frameHdr(const Mem &m) {
  const uint8_t st = marble_physics::state(m);
  const bool drawn = st == marble_physics::DIZZY || st == marble_physics::BROKEN ||
                     st == ST_EATEN || st == ST_DISSOLVE;
  return m.rb(PLAYER + VISIBLE) && drawn ? m.roml(m.rl(PLAYER + ANIM)) : 0;
}

static uint32_t shardHdr(const Mem &m) {
  return m.rb(PLAYER + VISIBLE) && m.rb(PLAYER + SHARDS_ON) ? m.roml(m.rl(PLAYER + SHARDS)) : 0;
}

// first field of tick t that differs, nullptr if none
static const char *diff(const Mem &m, const MarbleDeathTick &t) {
  if (marble_physics::x(m) != t.x) { return "x"; }
  if (marble_physics::y(m) != t.y) { return "y"; }
  if (marble_physics::z(m) != t.z) { return "z"; }
  if (marble_physics::state(m) != t.state) { return "state"; }
  if (m.rb(PLAYER + VISIBLE) != t.vis) { return "vis"; }
  if (m.sw(PLAYER + SX) != t.sx) { return "sx"; }
  if (m.sw(PLAYER + SY) != t.sy) { return "sy"; }
  if (m.rl(PLAYER + ANIM) != t.anim) { return "anim"; }
  if (frameHdr(m) != t.frame_hdr) { return "frame_hdr"; }
  if (shardHdr(m) != t.shard_hdr) { return "shard_hdr"; }
  if (memcmp(ram + (PLAYER + MASKS - marble_physics::RAM_BASE), t.mask, MASK_BYTES)) {
    return "mask";
  }
  if (m.rw(RNG) != t.rng) { return "rng"; }
  return nullptr;
}

// One main loop tick as marble_sim.py main_tick: 0x400010 and the camera long are inputs (the
// race timer is not run), then 0x1344c, band spawns, player 0x251de, slots 0x12fd0, rng.
static void mainTick(Mem &m, int8_t c6, int8_t c7, uint32_t camera, uint32_t frames) {
  m.wl(marble_physics::FRAMES, frames);
  marble_objects::applyQueued(m);
  const uint16_t old = m.rw(marble_physics::CAMERA);
  m.wl(marble_physics::CAMERA_L, camera);
  if ((uint16_t)camera != old) { marble_objects::cameraBands(m, old, (int16_t)camera); }
  marble_physics::tick(m, c6, c7);
  marble_objects::update(m);
  marble_rng::rng(m, RNG_TICK);
}

static void replayTick(Mem &m, const MarbleDeathTick &t) {
  mainTick(m, t.c6, t.c7, t.camera, t.frames);
}

// MAME player bytes after the last tick of each segment (pd1/bd2 traces; not in the
// fixture): score +0xbc, distance +0xc4 (0x26214), death count +0xd2
struct SegEnd { uint32_t score; uint16_t distance, deaths; };
static const SegEnd SEG_END[] = {{0, 0x60, 0}, {0x0a, 0x38, 1}, {0x28, 0x57, 2}, {0x32, 0x7c, 2}};

static void test_replay_deaths(void) {
  TEST_ASSERT_EQUAL(MARBLE_DEATHS_SEGMENTS, sizeof(SEG_END) / sizeof(SEG_END[0]));
  for (uint8_t s = 0; s < MARBLE_DEATHS_SEGMENTS; s++) {
    const MarbleDeathSegment &seg = marble_deaths_segments[s];
    loadRam(seg);
    Mem m(ram, seg.race);
    marble_drawlist::init(m);  // the fixture has no draw list; slot inserts need one

    for (uint16_t k = 0; k < seg.nticks; k++) {
      const MarbleDeathTick &t = seg.ticks[k];
      replayTick(m, t);
      const char *bad = diff(m, t);
      if (!bad) { continue; }

      char msg[200];
      snprintf(msg, sizeof(msg),
               "segment %d (race %d frame %u) tick %d: %s differs (state %d, expected %d, rng"
               " %04x / %04x)",
               s, seg.race, (unsigned)seg.frame, k, bad, marble_physics::state(m), t.state,
               m.rw(RNG), t.rng);
      TEST_FAIL_MESSAGE(msg);
    }

    char msg[60];
    snprintf(msg, sizeof(msg), "segment %d end: score, distance, deaths", s);
    TEST_ASSERT_EQUAL_HEX32_MESSAGE(SEG_END[s].score, m.rl(PLAYER + SCORE), msg);
    TEST_ASSERT_EQUAL_HEX16_MESSAGE(SEG_END[s].distance, m.rw(PLAYER + DISTANCE), msg);
    TEST_ASSERT_EQUAL_HEX16_MESSAGE(SEG_END[s].deaths, m.rw(PLAYER + DEATHS), msg);
  }
}

// ---------------------------------------------------------------- player objects

// One player MO as the published state draws it: race pixel top left, height, MO code (0 for a
// frame column: tile only), death set tile, palette set, hflip, priority (mask)
struct DrawnMo {
  int16_t x, top;
  uint8_t h;
  uint16_t code, tile;
  uint8_t set;
  bool flip, mask;
};

static const uint16_t NO_TILE = 0xffff;
static const uint8_t PAL_SHARDS = 2;  // palette set of the overlay (code | 0x1000)

static uint8_t addMasks(const marble_video::VideoState &v, uint8_t first, uint8_t n, int16_t ox,
                        int16_t oy, DrawnMo *out, uint8_t k) {
  for (uint8_t i = first; i < first + n; i++) {
    const marble_video::Mask &e = v.masks[i];
    const uint8_t h = ((e.code >> 11) & 7) + 1;
    out[k++] = {(int16_t)(ox + e.dx), (int16_t)(oy + e.dy), h, (uint16_t)(e.code & 0x7ff),
                NO_TILE, 0, (e.code & 0x8000) != 0, true};
  }
  return k;
}

// Player MOs of v in link order: marble masks, or per death object its columns (stars: one
// tile) then its masks. Marble halves, dots and 0x07 are not listed (the marble flag is).
static uint8_t playerMos(const marble_video::VideoState &v, int16_t sx, int16_t sy, int16_t top,
                         DrawnMo *out) {
  using namespace marble_video;
  uint8_t k = 0;
  if (v.marble == SHOWN) {
    const int16_t mx = sx + MARBLE_X, my = top + ARCADE_H + MARBLE_Y - sy;  // marble.cpp
    return addMasks(v, v.mask, v.nmask, mx, my, out, k);
  }
  const MarbleSpriteSet &s = marble_physics::deathSet();
  for (uint8_t i = 0; i < v.n && i < OBJS; i++) {
    const Obj &o = v.objs[i];
    if (!(o.set & SET_DEATH)) { continue; }
    const uint8_t pal = (o.set & SET_SHARDS) ? PAL_SHARDS : 0;
    if (o.set & SET_STAR) {
      out[k++] = {o.x, o.y, 1, (uint16_t)(MARBLE_STAR_CODE + o.frame),
                  (uint16_t)(MARBLE_STAR_TILE + o.frame), pal, false, false};
    } else {
      const MarbleSpriteFrame &f = s.frames[o.frame];
      for (uint8_t c = 0; c < f.ncols; c++) {
        const MarbleSpriteCol &col = s.cols[f.first + c];
        out[k++] = {(int16_t)(o.x + col.x), (int16_t)(o.y + col.y), (uint8_t)(col.h & 0x7f), 0,
                    col.tile, pal, (col.h & 0x80) != 0, false};
      }
    }
    k = addMasks(v, o.mask, o.nmask, o.x, o.y, out, k);
  }
  return k;
}

// MO RAM words of d (MO x = race x + 24, MO y counts up: top line = 256 - MO y - 8 h)
static MarbleDeathMo moWords(const DrawnMo &d, int16_t top) {
  const uint16_t y = (uint16_t)(top + 256 - d.top - 8 * d.h);
  const uint16_t x = (uint16_t)(d.x + 24);
  return {(uint16_t)(((y << 5) & 0x3fe0) | (d.flip ? 0x8000 : 0) | (d.h - 1)),
          (uint16_t)(d.code | d.set << 11), (uint16_t)(((x << 5) & 0x3fe0) | (d.mask ? 0x8000 : 0))};
}

// Published player (build) against the player MOs MAME emitted in every death fixture tick:
// death frames (header, columns: position, height, flip, palette set), sparkle stars, masks;
// the marble shown exactly when MAME draws its 0x05 half. Frame column codes are not in the
// remake: one code must map to one tile, in code order (sorted death set).
static void test_player_objects(void) {
  static const uint16_t HALF = 0x05, CODES = 0x800;
  static uint16_t tileOf[CODES];
  for (uint16_t &t : tileOf) { t = NO_TILE; }
  const MarbleSpriteSet &s = marble_physics::deathSet();
  uint16_t frames = 0, stars = 0, masks = 0;

  for (uint8_t sg = 0; sg < MARBLE_DEATHS_SEGMENTS; sg++) {
    const MarbleDeathSegment &seg = marble_deaths_segments[sg];
    loadRam(seg);
    Mem m(ram, seg.race);
    marble_drawlist::init(m);
    const int16_t descTop = (int16_t)m.romw(m.desc() + marble_physics::DESC_TOP);

    for (uint16_t k = 0; k < seg.nticks; k++) {
      const MarbleDeathTick &t = seg.ticks[k];
      replayTick(m, t);
      marble_drawlist::sort(m);
      marble_video::VideoState v = {};
      marble_drawlist::build(m, (int16_t)t.camera, 24, v);
      const int16_t top = (int16_t)((int16_t)t.camera - descTop);

      char msg[160];
      snprintf(msg, sizeof(msg), "segment %d tick %d (state %d)", sg, k, t.state);
      bool half = false;
      for (uint16_t i = 0; i < t.n; i++) { half |= seg.mos[t.first + i].code == HALF; }
      TEST_ASSERT_EQUAL_MESSAGE(half, v.marble == marble_video::SHOWN, msg);

      DrawnMo got[40];
      const uint8_t n = playerMos(v, t.sx, t.sy, top, got);
      uint8_t j = 0;  // fixture MO
      for (uint16_t i = 0; i < t.n; i++) {
        const MarbleDeathMo &e = seg.mos[t.first + i];
        const bool mask = (e.w2 & 0x8000) != 0;
        if (half && !mask) { continue; }  // marble halves, dots, 0x07
        TEST_ASSERT_TRUE_MESSAGE(j < n, msg);
        const MarbleDeathMo w = moWords(got[j], top);
        TEST_ASSERT_EQUAL_HEX16_MESSAGE(e.w0, w.w0, msg);
        TEST_ASSERT_EQUAL_HEX16_MESSAGE(e.w2, w.w2, msg);
        if (got[j].code) {
          TEST_ASSERT_EQUAL_HEX16_MESSAGE(e.code, w.code, msg);
        } else {
          TEST_ASSERT_EQUAL_HEX16_MESSAGE(e.code >> 11, got[j].set, msg);
        }
        const uint16_t c = e.code & 0x7ff;
        if (got[j].tile != NO_TILE) {
          TEST_ASSERT_TRUE_MESSAGE(tileOf[c] == NO_TILE || tileOf[c] == got[j].tile, msg);
          tileOf[c] = got[j].tile;
        }
        masks += mask;
        stars += got[j].code && !mask;
        frames += !got[j].code;
        j++;
      }
      TEST_ASSERT_EQUAL_UINT8_MESSAGE(j, n, msg);

      // the frame drawn is the fixture's header
      for (uint8_t i = 0; i < v.n; i++) {
        const marble_video::Obj &o = v.objs[i];
        if (!(o.set & marble_video::SET_DEATH) || (o.set & marble_video::SET_STAR)) { continue; }
        const uint32_t hdr = FRAMES_BASE + 2 * (uint32_t)s.addr[o.frame];
        TEST_ASSERT_EQUAL_HEX32_MESSAGE((o.set & marble_video::SET_SHARDS) ? t.shard_hdr
                                                                           : t.frame_hdr,
                                        hdr, msg);
      }
    }
  }

  uint16_t last = 0;
  bool first = true;
  for (uint16_t c = 0; c < CODES; c++) {
    if (tileOf[c] == NO_TILE) { continue; }
    TEST_ASSERT_TRUE_MESSAGE(first || tileOf[c] > last, "death tiles not in code order");
    last = tileOf[c];
    first = false;
  }
  printf("player MOs compared: %d frame columns, %d stars, %d masks\n", frames, stars, masks);
  TEST_ASSERT_TRUE(frames > 0 && stars > 0 && masks > 0);
}

// ---------------------------------------------------------------- race start sweep

static const uint8_t RACES = 6;
static const uint16_t RESPAWN_TICKS = 300;
static const uint8_t SETTLE_TICKS = 2;   // ticks before a death is forced
static const uint8_t DEAD_TICKS = 5;     // ticks into the death before the race switch
static const int16_t FALL_PX = 200;      // above the ground: falls past 128 px, lost
static const int16_t DROP_PX = 40;       // above the ground: lands and breaks
static const int16_t EMBED_PX = -20;     // below the terrain: embedded, lost

// marble.cpp beginRace: cleared work RAM, race start, camera, projection, masks
static void beginRace(uint8_t race) {
  memset(ram, 0, sizeof(ram));
  Mem m(ram, race);
  marble_physics::startRace(m, race);
  marble_camera::start(m, race);
  marble_physics::project(m);
  marble_occlusion::enter(m, PLAYER);
}

// marble.cpp run_frame + logicTick of a logic frame, no input
static void logicTick(Mem &m) {
  m.wl(marble_physics::FRAMES, m.rl(marble_physics::FRAMES) + 1);
  marble_objects::applyQueued(m);
  const int16_t oldCam = m.sw(marble_physics::CAMERA);
  marble_camera::tick(m);
  const int16_t newCam = m.sw(marble_physics::CAMERA);
  if (newCam != oldCam) { marble_objects::cameraBands(m, oldCam, newCam); }
  marble_physics::tick(m, 0, 0);
  marble_objects::update(m);
  marble_rng::rng(m, RNG_TICK);
  marble_drawlist::sort(m);

  marble_video::VideoState v = {};
  marble_drawlist::build(m, m.sw(marble_physics::CAMERA), 24, v);
}

// the marble dz pixels above (below) its z; above: airborne, fall height from there
static void displace(Mem &m, int16_t dz) {
  const uint32_t z = m.rl(PLAYER + PZ) + ((uint32_t)(int32_t)dz << 16);
  m.wl(PLAYER + PZ, z);
  if (dz < 0) { return; }
  m.wl(PLAYER + GROUND_Z, z);
  m.wb(PLAYER + AIR, AIRBORNE);
  m.wl(PLAYER + VZ, 0);
}

// frame header at hdr in the death set (no abort on a miss)
static bool inDeathSet(uint32_t hdr) {
  const MarbleSpriteSet &s = marble_physics::deathSet();
  for (uint8_t i = 0; i < s.nhdr; i++) {
    if (FRAMES_BASE + 2 * (uint32_t)s.addr[i] == hdr) { return true; }
  }
  return false;
}

// every frame the tick draws resolves in the death set
static void checkFrames(const Mem &m, uint8_t race, uint16_t k) {
  const uint8_t st = marble_physics::state(m);
  char msg[80];
  if ((st == marble_physics::DIZZY || st == marble_physics::BROKEN) && m.rl(PLAYER + ANIM)) {
    const uint32_t hdr = m.roml(m.rl(PLAYER + ANIM));
    snprintf(msg, sizeof(msg), "race %d tick %d: frame %06x not in the death set", race, k,
             (unsigned)hdr);
    TEST_ASSERT_TRUE_MESSAGE(inDeathSet(hdr), msg);
  }
  if (m.rb(PLAYER + SHARDS_ON)) {
    const uint32_t hdr = m.roml(m.rl(PLAYER + SHARDS));
    snprintf(msg, sizeof(msg), "race %d tick %d: overlay %06x not in the death set", race, k,
             (unsigned)hdr);
    TEST_ASSERT_TRUE_MESSAGE(inDeathSet(hdr), msg);
  }
}

// Forces a death dz px off the ground and runs until the marble rolls again. Returns the
// states seen as bits.
static uint16_t dieAndRespawn(uint8_t race, int16_t dz) {
  beginRace(race);
  Mem m(ram, race);
  for (uint8_t k = 0; k < SETTLE_TICKS; k++) { logicTick(m); }
  displace(m, dz);

  uint16_t seen = 0;
  bool dead = false;
  for (uint16_t k = 0; k < RESPAWN_TICKS; k++) {
    logicTick(m);
    const uint8_t st = marble_physics::state(m);
    seen |= 1 << st;
    checkFrames(m, race, k);
    if (st == marble_physics::BROKEN || st == marble_physics::LOST) { dead = true; }
    if (dead && st == marble_physics::ROLL) {
      printf("race %d dz %d: rolls again after %d ticks, states %03x\n", race, dz, k + 1, seen);
      return seen;
    }
  }
  char msg[80];
  snprintf(msg, sizeof(msg), "race %d dz %d: no respawn in %d ticks (dead %d, state %d)", race,
           dz, RESPAWN_TICKS, dead, marble_physics::state(m));
  TEST_FAIL_MESSAGE(msg);
  return seen;
}

static void test_race_start_sweep(void) {
  static const uint16_t BROKE = 1 << marble_physics::BROKEN, LOST = 1 << marble_physics::LOST;
  for (uint8_t race = 0; race < RACES; race++) {
    char msg[60];
    snprintf(msg, sizeof(msg), "race %d: fall not lost", race);
    TEST_ASSERT_TRUE_MESSAGE(dieAndRespawn(race, FALL_PX) & LOST, msg);
    snprintf(msg, sizeof(msg), "race %d: drop did not shatter", race);
    TEST_ASSERT_TRUE_MESSAGE(dieAndRespawn(race, DROP_PX) & BROKE, msg);
    snprintf(msg, sizeof(msg), "race %d: embedded not lost", race);
    TEST_ASSERT_TRUE_MESSAGE(dieAndRespawn(race, EMBED_PX) & LOST, msg);
  }
}

// crc32 of player 1 (dots zeroed: 0x1c014 not ported) and the RNG word, as make_fixture.py
// start_crc
static uint32_t startCrc(const Mem &m) {
  uint8_t b[PLAYER_BYTES + 2];
  for (uint8_t o = 0; o < PLAYER_BYTES; o++) {
    const bool dot = (o >= MARBLE_DOTS_LO && o < MARBLE_DOTS_HI) || o == MARBLE_DOTS_K;
    b[o] = dot ? 0 : m.rb(PLAYER + o);
  }
  b[PLAYER_BYTES] = m.rb(RNG);
  b[PLAYER_BYTES + 1] = m.rb(RNG + 1);

  uint32_t crc = ~0u;
  for (uint8_t v : b) {
    crc ^= v;
    for (uint8_t k = 0; k < 8; k++) { crc = (crc >> 1) ^ (0xedb88320u & (0u - (crc & 1))); }
  }
  return ~crc;
}

// make_fixture.py place_goal: marble on the middle cell of the first goal line (zone list
// 0x1eb16), z on the terrain, rolling MARBLE_GOAL_V towards zone 0xff, zone of the other side
static void placeGoal(Mem &m, uint8_t race) {
  static const uint32_t ZONE_LISTS = 0x1eb16;
  static const uint8_t GOAL_ZONE = 0xff, LINE = 6;
  uint32_t a0 = m.roml(ZONE_LISTS + 4 * race);
  while (m.romb(a0 + 3) != GOAL_ZONE && m.romb(a0 + 4) != GOAL_ZONE) { a0 += LINE; }
  TEST_ASSERT_FALSE(m.romb(a0 + 3) == GOAL_ZONE && m.romb(a0 + 4) == GOAL_ZONE);

  const int8_t x = (int8_t)m.romb(a0), y = (int8_t)m.romb(a0 + 1), end = (int8_t)m.romb(a0 + 2);
  const bool horiz = x < 0;
  const int16_t ax = x < 0 ? -x : x, ay = y < 0 ? -y : y;
  const int16_t mid = ((horiz ? ax : ay) + end) / 2;
  const int16_t cx = horiz ? mid : ax, cy = horiz ? ay : mid;
  const bool up = m.romb(a0 + 4) == GOAL_ZONE;

  m.wl(PLAYER + PX, (uint32_t)(cx * 8 + 4) << 16);
  m.wl(PLAYER + PY, (uint32_t)(cy * 8 + 4) << 16);
  m.ww(marble_physics::CELL_Y, 0xffff);
  m.ww(marble_physics::CELL_X, 0xffff);
  marble_physics::posupd_1bab2(m, PLAYER);
  const uint32_t z = (uint32_t)marble_physics::height_1cc62(m);
  m.wl(PLAYER + PZ, z);
  m.wl(PLAYER + GROUND_Z, z);
  m.wb(PLAYER + ZONE, m.romb(a0 + (up ? 3 : 4)));
  m.wb(PLAYER + AIR, 0);
  m.wl(PLAYER + (horiz ? VY : VX), (uint32_t)(up ? MARBLE_GOAL_V : -MARBLE_GOAL_V));
}

static void runFail(const MarbleStartRun &r, int16_t k, const char *what) {
  char msg[100];
  snprintf(msg, sizeof(msg), "race %d %s tick %d: %s", r.race, r.goal ? "goal" : "start", k,
           what);
  TEST_FAIL_MESSAGE(msg);
}

// Remake start (beginRace) and ticks equal the model (marble_start_trace.h): stick input from
// the start, and the goal crossing. Goal 0x254d2: +0x57 reaches 0 after 0x1e ticks: out of
// play (+0x18 = 3), v = 0; it wraps to 0xff and repeats 256 ticks later.
static void test_start_and_goal(void) {
  static const uint8_t OUT_OF_PLAY = 3;
  static const uint16_t WRAP = 256;
  for (uint8_t i = 0; i < MARBLE_START_RUNS; i++) {
    const MarbleStartRun &r = marble_start_runs[i];
    beginRace(r.race);
    Mem m(ram, r.race);
    if (startCrc(m) != r.crc0) { runFail(r, -1, "player after beginRace differs"); }
    if (r.goal) { placeGoal(m, r.race); }

    const uint16_t n = r.goal ? MARBLE_GOAL_TICKS : MARBLE_START_TICKS;
    int16_t out = -1;  // tick of the first out of play write
    uint8_t outs = 0;
    for (uint16_t k = 0; k < n; k++) {
      const int8_t c6 = r.goal ? 0 : marble_start_input[k][0];
      const int8_t c7 = r.goal ? 0 : marble_start_input[k][1];
      mainTick(m, c6, c7, r.camera, k + 1);
      if (startCrc(m) != r.crc[k]) { runFail(r, k, "player or rng differs from the model"); }
      if (!r.goal || marble_physics::state(m) != marble_physics::GOAL || m.rb(PLAYER + DAMAGE)) {
        continue;
      }

      // goal countdown at 0: out of play, v = 0
      if (m.rb(PLAYER + SLOT) != OUT_OF_PLAY || m.rl(PLAYER + VX) || m.rl(PLAYER + VY)) {
        runFail(r, k, "goal end: slot 3, v = 0 expected");
      }
      if (out >= 0 && k - out != WRAP) { runFail(r, k, "goal end not 256 ticks later"); }
      if (out < 0) { out = k; }
      outs++;
    }
    if (r.goal && outs != 2) { runFail(r, n, "goal end not seen twice"); }
  }
}

// RNG consumers of the race start (0x10fb8 byte, random slot groups): model start_race on a
// cleared work RAM gives 0x4003a6 = 0x0102, 0x400444 = 2, 0x40076c = 1 in every race
static void test_race_start_rng(void) {
  static const uint32_t TIMEOUT_RND = 0x400444, TIMEOUT_ARMED = 0x40076c;
  for (uint8_t race = 0; race < RACES; race++) {
    beginRace(race);
    Mem m(ram, race);
    TEST_ASSERT_EQUAL_HEX16(0x0102, m.rw(RNG));
    TEST_ASSERT_EQUAL_HEX8(2, m.rb(TIMEOUT_RND));
    TEST_ASSERT_EQUAL_HEX8(1, m.rb(TIMEOUT_ARMED));
  }
}

// FIRE while dead: the next race starts from a dying marble in state 0, no stars or death
// frame left
static void test_race_switch_dead(void) {
  static const int16_t drops[] = {FALL_PX, DROP_PX};
  for (uint8_t race = 0; race < RACES; race++) {
    for (int16_t dz : drops) {
      beginRace(race);
      Mem m(ram, race);
      for (uint8_t k = 0; k < SETTLE_TICKS; k++) { logicTick(m); }
      displace(m, dz);
      uint16_t k = 0;
      while (marble_physics::state(m) == marble_physics::ROLL && k++ < RESPAWN_TICKS) {
        logicTick(m);
      }
      for (uint8_t i = 0; i < DEAD_TICKS; i++) { logicTick(m); }
      TEST_ASSERT_NOT_EQUAL(marble_physics::ROLL, marble_physics::state(m));

      const uint8_t next = (race + 1) % RACES;
      beginRace(next);
      Mem n(ram, next);
      TEST_ASSERT_EQUAL_UINT8(marble_physics::ROLL, marble_physics::state(n));
      TEST_ASSERT_EQUAL_UINT8(1, n.rb(PLAYER + SLOT));
      TEST_ASSERT_EQUAL_UINT32(0, n.rl(PLAYER + ANIM));
      TEST_ASSERT_EQUAL_UINT8(0, n.rb(PLAYER + SHARDS_ON));
      for (uint8_t e = 0; e < MASK_BYTES; e += MASK_ENTRY) {
        const uint16_t code = n.rw(PLAYER + MASKS + e);
        TEST_ASSERT_TRUE_MESSAGE(!code || (code & MASK_BIT), "star left in +0x38");
      }
      logicTick(n);
      TEST_ASSERT_EQUAL_UINT8(marble_physics::ROLL, marble_physics::state(n));
      marble_video::VideoState v = {};  // no death object left
      marble_drawlist::build(n, n.sw(marble_physics::CAMERA), 24, v);
      TEST_ASSERT_EQUAL_UINT8(marble_video::SHOWN, v.marble);
      for (uint8_t i = 0; i < v.n; i++) {
        TEST_ASSERT_FALSE(v.objs[i].set & marble_video::SET_DEATH);
      }
    }
  }
}
#endif

int main(int, char **) {
  UNITY_BEGIN();
#ifdef HAVE_ROM
  RUN_TEST(test_replay_deaths);
  RUN_TEST(test_player_objects);
  RUN_TEST(test_race_start_rng);
  RUN_TEST(test_start_and_goal);
  RUN_TEST(test_race_start_sweep);
  RUN_TEST(test_race_switch_dead);
#else
  TEST_IGNORE_MESSAGE("marble_rom.h missing, run romconv ./convert.sh marble");
#endif
  return UNITY_END();
}
